def run(_context):
    import adsk.core, adsk.fusion, adsk.cam
    app = adsk.core.Application.get()
    doc = app.activeDocument
    cam = adsk.cam.CAM.cast(doc.products.itemByProductType('CAMProductType'))
    setup = cam.setups.item(0)
    print("Setup name:", setup.name)
    print("OperationType:", setup.operationType)
    # WCS
    try:
        params = setup.parameters
        for p in params:
            try:
                v = p.expression
            except:
                v = None
            if any(k in p.name.lower() for k in ['wcs','origin','stock','offset','orient','model','side','top','bottom']):
                print("PARAM", p.name, "=", v)
    except Exception as e:
        print("param err", e)
    return "ok"

def run(_context):
    import adsk.core, adsk.fusion, adsk.cam
    app = adsk.core.Application.get()
    camMgr = adsk.cam.CAMManager.get()
    libs = camMgr.libraryManager.toolLibraries
    # enumerate library urls
    found = []
    def walk(url, depth=0):
        try:
            childs = libs.childFolderURLs(url)
        except:
            childs = []
        for c in childs:
            print("FOLDER", c.leafName, c.toString())
            walk(c, depth+1)
        try:
            liburls = libs.childAssetURLs(url)
        except:
            liburls = []
        for lu in liburls:
            print("LIB", lu.leafName, lu.toString())
            found.append(lu)
    root = libs.urlByLocation(adsk.cam.LibraryLocations.LocalLibraryLocation)
    walk(root)
    return "ok"

