def run(_context):
    import adsk.core, adsk.fusion, adsk.cam
    app = adsk.core.Application.get()
    camMgr = adsk.cam.CAMManager.get()
    libs = camMgr.libraryManager.toolLibraries
    url = libs.urlByLocation(adsk.cam.LibraryLocations.LocalLibraryLocation)
    for lu in libs.childAssetURLs(url):
        if 'TIW' in lu.leafName:
            lib = libs.toolLibraryAtURL(lu)
            print("Tools in", lu.leafName, ":", lib.count)
            for i in range(lib.count):
                t = lib.item(i)
                tt = t.parameters.itemByName('tool_type').value.value
                try:
                    d = t.parameters.itemByName('tool_diameter').value.value*10
                except:
                    d = None
                try:
                    num = t.parameters.itemByName('tool_number').value.value
                except:
                    num = None
                desc = ''
                try:
                    desc = t.parameters.itemByName('tool_description').value.value
                except: pass
                print("#%s T%s type=%s dia=%s desc=%s"%(i,num,tt,d,desc))
    return "ok"

