    import json
    tools = mb.list_library_tools(contains="TIW")
    # find our desired ones
    want = {}
    for t in tools:
        d = t['description']
        if d == '1/2" 3Fl Carb TiCN Flat Endmill': want['half_flat']=t
        if d == '1/4" 3fl TiCN Carb Flat Endmill': want['quarter_flat']=t
        if d == '1/4" Cobalt Drill': want['quarter_drill']=t
    for k,v in want.items():
        print(k, v['index'], v['description'], v['diameter_mm'], v['library_url'])
    return "ok"

